mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("text=abracadabra pattern=abra","0,7"),
        ("text=aaaa pattern=aa","0,1,2"),
        ("text=abcabc pattern=bc","1,4"),
        ("text=abc pattern=z",""),
        ("text=aaaaa pattern=aaa","0,1,2"),
        ("  \ntext=abracadabra pattern=abra\n  ","0,7"),
        ("\ntext=aaaaa pattern=aaa\n","0,1,2")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS rabin-karp");
}
